import{c as a,Q as n,j as s,m as e}from"./chunks/framework.DOi4mjdC.js";const i="/assets/%E6%B5%81%E6%B0%B4%E4%BB%BB%E5%8A%A1%E8%BF%90%E8%A1%8C%E7%A4%BA%E6%84%8F%E5%9B%BE-45.BVso-s04.png",_=JSON.parse('{"title":"DumpAccChkPoint","description":"","frontmatter":{},"headers":[{"level":1,"title":"DumpAccChkPoint","slug":"dumpaccchkpoint"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/调试接口/上板打印/DumpAccChkPoint.md","filePath":"api/SIMD-API/基础API/调试接口/上板打印/DumpAccChkPoint.md"}'),l={name:"api/SIMD-API/基础API/调试接口/上板打印/DumpAccChkPoint.md"};function p(o,t,d,r,c,u){return n(),s("div",null,[...t[0]||(t[0]=[e(`<h1 id="dumpaccchkpoint" tabindex="-1">DumpAccChkPoint <a class="header-anchor" href="#dumpaccchkpoint" aria-label="Permalink to &quot;DumpAccChkPoint&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr><tr><td>Kirin X90</td><td>√</td></tr><tr><td>Kirin 9030</td><td>√</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>基于算子工程开发的算子，可以使用该接口Dump指定Tensor的内容。同时支持打印自定义的附加信息（仅支持uint32_t数据类型的信息），比如打印当前行号等。区别于<a href="./DumpTensor.html">DumpTensor</a>，使用该接口可以支持指定偏移位置的Tensor打印。</p><p>在算子kernel侧实现代码中需要打印偏移后Tensor数据的地方调用DumpAccChkPoint接口打印相关内容。样例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AscendC::DumpAccChkPoint(srcLocal, 5, 32, dataLen);</span></span></code></pre></div><div class="caution custom-block github-alert"><p class="custom-block-title">注意</p><p>DumpAccChkPoint接口打印功能会对算子实际运行的性能带来一定影响，通常在调测阶段使用。开发者可以按需通过设置ASCENDC_DUMP=0来关闭打印功能。</p></div><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T&gt;</span></span>
<span class="line"><span>__aicore__ inline void DumpAccChkPoint(const LocalTensor&lt;T&gt; &amp;tensor, uint32_t index, uint32_t countOff, uint32_t dumpSize)</span></span>
<span class="line"><span>template &lt;typename T&gt;</span></span>
<span class="line"><span>__aicore__ inline void DumpAccChkPoint(const GlobalTensor&lt;T&gt; &amp;tensor, uint32_t index, uint32_t countOff, uint32_t dumpSize)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>需要dump的Tensor的数据类型。 Ascend 950PR/Ascend 950DT，支持的数据类型为：bool、uint8_t、int8_t、int16_t、uint16_t、int32_t、uint32_t、int64_t、uint64_t、float、half、bfloat16_t。 Atlas A3 训练系列产品/Atlas A3 推理系列产品，支持的数据类型为：bool、uint8_t、int8_t、int16_t、uint16_t、int32_t、uint32_t、int64_t、uint64_t、float、half、bfloat16_t。 Atlas A2 训练系列产品/Atlas A2 推理系列产品，支持的数据类型为：bool、uint8_t、int8_t、int16_t、uint16_t、int32_t、uint32_t、int64_t、uint64_t、float、half、bfloat16_t。 Atlas 推理系列产品AI Core，支持的数据类型为：bool、uint8_t、int8_t、int16_t、uint16_t、int32_t、uint32_t、int64_t、uint64_t、float、half。 Kirin X90，支持的数据类型为：bool、uint8_t、int8_t、int16_t、uint16_t、int32_t、uint32_t、int64_t、uint64_t、float、half。 Kirin 9030，支持的数据类型为：bool、uint8_t、int8_t、int16_t、uint16_t、int32_t、uint32_t、int64_t、uint64_t、float、half。</td></tr></tbody></table><p><strong>表 2</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>tensor</td><td>输入</td><td>需要dump的Tensor。 待dump的tensor位于Unified Buffer/L1 Buffer/L0C Buffer时使用LocalTensor类型的tensor参数输入。 待dump的tensor位于Global Memory时使用GlobalTensor类型的tensor参数输入。</td></tr><tr><td>index</td><td>输入</td><td>用户自定义附加信息（行号或其他自定义数字）。</td></tr><tr><td>countOff</td><td>输入</td><td>偏移元素个数。偏移后的Tensor地址需要满足所在物理位置的对齐约束，具体参考通用说明和约束。</td></tr><tr><td>dumpSize</td><td>输入</td><td>需要dump的元素个数。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li><p>该功能仅用于NPU上板调试。</p></li><li><p>暂不支持算子入图场景的打印。</p></li><li><p>当前仅支持打印存储位置为Unified Buffer/L1 Buffer/L0C Buffer/Global Memory的Tensor信息。针对Ascend 950PR/Ascend 950DT，不支持打印L1 Buffer上的Tensor信息。</p></li><li><p>操作数地址对齐要求请参见<a href="./../../../通用说明和约束.html#section796754519912">通用地址对齐约束</a>。</p></li><li><p>单次调用DumpTensor打印的数据总量不可超过1MB（还包括少量框架需要的头尾信息，通常可忽略）。使用时应注意，如果超出这个限制，则数据不会被打印。</p></li><li><p>在计算数据量时，若Dump的总长度未对齐，需要考虑padding数据的影响。当进行非对齐Dump时，如果实际Dump的元素长度不满足32字节对齐，系统会在其末尾自动补充一定数量的padding数据，以满足对齐要求。例如，Tensor1中用户需要Dump的元素长度为30字节，系统会在其后添加2字节的padding，使总长度对齐到32字节。但在实际解析时，仍只解析原始的30字节数据，padding部分不会被使用。</p></li><li><p>使用自定义算子工程进行算子开发时，接口的打印信息和上文描述有些差异：</p><p>Dump时，每个block核的dump信息前会增加对应信息头DumpHead，用于记录核号和资源使用信息；每次Dump的Tensor数据前也会添加信息头DumpTensorHead，用于记录Tensor的相关信息。如下图所示，展示了多核打印场景下的打印信息结构。</p><p><img src="`+i+`" alt=""></p><p><strong>DumpHead的具体信息如下：</strong></p><ul><li>opType：当前运行的算子类型；</li><li>CoreType：当前运行的核的类型；</li><li>block dim：开发者设置的算子执行核数；</li><li>total_block_num：参与dump的核数；</li><li>block_remain_len：当前核剩余可用的dump的空间；</li><li>block_initial_space：当前核初始分配的dump空间；</li><li>rsv：保留字段；</li><li>magic：内存校验魔术字。</li></ul><p>DumpHead打印时，除了上述打印还会自动打印当前所运行核的类型及对应的该类型下的核索引，如：AIV-0。</p><p><strong>DumpTensorHead的具体信息如下：</strong></p><ul><li>desc：用户自定义附加信息；</li><li>addr：Tensor的地址；</li><li>data_type：Tensor的数据类型；</li><li>position：表示Tensor所在的物理存储位置，当前仅支持Unified Buffer/L1 Buffer/L0C Buffer/Global Memory。</li><li>dump_size：表示用户需要dump的元素个数。</li></ul><p>DumpAccChkPoint打印结果的最前面会自动打印CANN_VERSION_STR值与CANN_TIMESTAMP值。其中，CANN_VERSION_STR与CANN_TIMESTAMP为宏定义，CANN_VERSION_STR代表CANN软件包的版本号信息，形式为字符串，CANN_TIMESTAMP为CANN软件包发布时的时间戳，形式为数值（uint64_t）。开发者也可在代码中直接使用这两个宏。</p><p>打印结果的样例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>opType=AddCustom, DumpHead: AIV-0, CoreType=AIV, block dim=8, total_block_num=8, block_remain_len=1046912, block_initial_space=1048576, rsv=0, magic=5aa5bccd </span></span>
<span class="line"><span>CANN Version: XX.XX,TimeStamp: XXXXXX</span></span>
<span class="line"><span>DumpTensor: desc=5, addr=40, data_type=float16, position=UB, dump_size=32</span></span>
<span class="line"><span>[16.000000, 22.000000, 2.000000, 3.000000, 58.000000, 62.000000, 33.000000, 74.000000, 51.000000, 69.000000, 61.000000, 9.000000, 53.000000, 35.000000, 14.000000, 43.000000, 20.000000, 43.000000, 92.000000, 84.000000, 9.000000, 6.000000, 78.000000, 53.000000, 52.000000, 33.000000, 51.000000, 61.000000, 92.000000, 45.000000, 39.000000,34.000000]</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>DumpTensor: desc=5, addr=140, data_type=float16, position=UB, dump_size=32</span></span>
<span class="line"><span>[41.000000, 91.000000, 12.000000, 32.000000, 28.000000, 49.000000, 2.000000, 75.000000, 11.000000, 32.000000, 17.000000, 31.000000, 70.000000, 38.000000, 76.000000, 87.000000, 61.000000, 8.000000, 55.000000, 70.000000, 17.000000, 37.000000, 35.000000, 58.000000, 94.000000, 31.000000, 50.000000, 29.000000, 13.000000, 37.000000, 79.000000,29.000000]</span></span></code></pre></div><p>该接口使用Dump功能，一个算子所有使用Dump功能的接口在每个核上Dump的数据总量不可超过1M。请开发者自行控制待打印的内容数据量，超出则不会打印。</p></li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>constexpr uint32_t totalLength = 256;    // 参与搬运的元素个数</span></span>
<span class="line"><span>AscendC::LocalTensor&lt;half&gt; srcLocal;</span></span>
<span class="line"><span>AscendC::GlobalTensor&lt;half&gt; srcGlobal;</span></span>
<span class="line"><span>AscendC::DataCopy(srcLocal, srcGlobal, totalLength * sizeof(half));</span></span>
<span class="line"><span>uint32_t index = 8;    // 用户自定义附加信息，此处传入DumpAccChkPoint指令的行号</span></span>
<span class="line"><span>uint32_t countOff = 32;    // 偏移元素个数，从srcLocal[32]开始打印</span></span>
<span class="line"><span>uint32_t dupmSize = 128;    // dump的元素个数，从srcLocal[32]开始打印128个元素个数</span></span>
<span class="line"><span>AscendC::DumpAccChkPoint(srcLocal, index, countOff, dupmSize);</span></span></code></pre></div>`,21)])])}const m=a(l,[["render",p]]);export{_ as __pageData,m as default};
